package com.primehr.rsp.selection.api;import com.primehr.integration.administrative.EffectiveFeaturePermission;import com.primehr.rsp.selection.api.SelectionDtos.*;import com.primehr.rsp.selection.application.SelectionService;import com.primehr.security.*;import com.primehr.shared.api.PageResponse;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/primehr/v1/rsp/selection-cases") public class SelectionController{private final SelectionService service;private final RspSelectionDecisionPermissionGuard permission;private final AgencyScopeResolver agency;public SelectionController(SelectionService s,RspSelectionDecisionPermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}@GetMapping public PageResponse<CaseResponse>list(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){permission.require(PrimeHrAction.ACCESS,t);return service.list(agency.resolveAgencyId(a),page,size);}@GetMapping("/{id}")public CaseResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){permission.require(PrimeHrAction.ACCESS,t);return service.get(agency.resolveAgencyId(a),id);}@PostMapping @ResponseStatus(HttpStatus.CREATED)public CaseResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid @RequestBody CreateSelection r){permission.require(PrimeHrAction.ADD,t);return service.create(agency.resolveAgencyId(a),r,a.getName(),c);}@PutMapping("/{id}/decision")public CaseResponse decide(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody DecideSelection r){permission.require(PrimeHrAction.EDIT,t);return service.decide(agency.resolveAgencyId(a),id,r,a.getName(),c);}@PostMapping("/{id}/{action:submit|return|cancel}")public CaseResponse transition(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@PathVariable String action,@Valid @RequestBody Transition r){permission.require(action.equals("submit")?PrimeHrAction.SUBMIT:PrimeHrAction.EDIT,t);return service.transition(agency.resolveAgencyId(a),id,r,a.getName(),action,false,c);}@PostMapping("/{id}/approve")public CaseResponse approve(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition r){EffectiveFeaturePermission p=permission.require(PrimeHrAction.APPROVE,t);return service.transition(agency.resolveAgencyId(a),id,r,a.getName(),"approve",p.administrator(),c);}@PostMapping("/{id}/finalize")public CaseResponse finalizeCase(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition r){permission.require(PrimeHrAction.FINALIZE,t);return service.transition(agency.resolveAgencyId(a),id,r,a.getName(),"finalize",false,c);}@PostMapping("/{id}/successors")@ResponseStatus(HttpStatus.CREATED)public CaseResponse successor(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Successor r){permission.require(PrimeHrAction.ADD,t);return service.successor(agency.resolveAgencyId(a),id,r,a.getName(),c);}}
